-- Localization for the 10 Poki locales that the bundled Nunito-Black font can render
-- (Latin, Latin Extended and Cyrillic). CJK / Vietnamese / Arabic / Thai / Devanagari
-- need glyphs this font does not have, so they fall back to English here; the fonts are
-- validated by `node tools/check_fonts.js` and regenerated by `node tools/gen_font.js`.
local M = {}

-- Poki load order: EFIGS + Turkish, then pt-BR and Russian, then the remaining
-- Latin-script markets Poki serves (Polish, Dutch). The list drives the language picker.
M.LANGS = { "en", "es", "pt", "ru", "tr", "pl", "de", "fr", "it", "nl" }

local STRINGS = {
	en = require "main.modules.locales.en",
	es = require "main.modules.locales.es",
	pt = require "main.modules.locales.pt",
	ru = require "main.modules.locales.ru",
	tr = require "main.modules.locales.tr",
	pl = require "main.modules.locales.pl",
	de = require "main.modules.locales.de",
	fr = require "main.modules.locales.fr",
	it = require "main.modules.locales.it",
	nl = require "main.modules.locales.nl",
}

-- Native language names, shown in the picker and the settings button.
M.NAMES = {}
for code, strings in pairs(STRINGS) do M.NAMES[code] = strings.NAME end

-- Base code -> locale. PokiSDK.getLanguage() already returns a lowercase base code
-- ("pt" for pt-BR), these cover browsers that report a full tag.
local ALIASES = {
	pt_br = "pt",
	ptbr = "pt",
	es_419 = "es",
	es_latam = "es",
	en_us = "en",
	en_gb = "en",
	zh = "en",
	zh_hans = "en",
	zh_hant = "en",
	ja = "en",
	ko = "en",
	vi = "en",
	id = "en",
	["in"] = "en",
	th = "en",
	hi = "en",
	ar = "en",
	fa = "en",
	he = "en",
	uk = "ru",
	be = "ru",
	nb = "en",
	no = "en",
	da = "en",
	sv = "en",
	cs = "en",
	sk = "en",
	hu = "en",
	ro = "en",
	el = "en",
	fi = "en",
	hr = "en",
	sr = "en",
	bg = "en",
}

local function normalize(code)
	if type(code) ~= "string" then return nil end
	local c = string.lower(code)
	c = string.gsub(c, "-", "_")
	local base = string.match(c, "^([a-z]+)")
	if not base then return nil end
	if STRINGS[base] then return base end
	local alias = ALIASES[c] or ALIASES[base]
	if alias and STRINGS[alias] then return alias end
	return nil
end

M.lang = "en"

-- hint: language reported by PokiSDK.getLanguage() (preferred), then the OS locale.
function M.detect(hint)
	local lang = normalize(hint)
	if lang then return lang end
	if sys and sys.get_sys_info then
		lang = normalize(sys.get_sys_info().language)
		if lang then return lang end
	end
	return "en"
end

function M.set(lang)
	M.lang = normalize(lang) or "en"
end

-- Is this language supported? (used by tests and save-file migration)
function M.supported(lang)
	return normalize(lang) ~= nil
end

function M.has(key)
	return STRINGS[M.lang][key] ~= nil or STRINGS.en[key] ~= nil
end

function M.t(key, vars)
	local s = (STRINGS[M.lang] and STRINGS[M.lang][key]) or STRINGS.en[key] or key
	if vars then
		for k, v in pairs(vars) do
			s = string.gsub(s, "{" .. k .. "}", (string.gsub(tostring(v), "%%", "%%%%")))
		end
	end
	return s
end

function M.fmt_time(sec)
	sec = math.max(0, math.floor(sec))
	if sec >= 3600 then
		local h = math.floor(sec / 3600)
		local m = math.floor((sec % 3600) / 60)
		return M.t("TIME_H", { h = h, m = string.format("%02d", m) })
	elseif sec >= 60 then
		local m = math.floor(sec / 60)
		local s = sec % 60
		return string.format("%d:%02d", m, s)
	end
	return string.format("0:%02d", sec)
end

-- Debug helper for tests: every key of every language.
function M.keys(lang)
	local out = {}
	for k in pairs(STRINGS[lang or "en"]) do out[#out + 1] = k end
	return out
end

return M
